mapper.select:
select
con.Con_Name as conName, con.Con_Code as conCode, con.Con_Party_B_Agent as conPartyBAgent, con.Con_Party_B_Id as conPartyBId, con.Con_Party_B_Pm as conPartyBPm, c1.C_Name as conPartyBName, c1.C_Abbreviation as conPartyBAbbName, c2.C_Name as dgExplName, c2.C_Abbreviation as dgExplAbbName, sec.Sec_Name as secName, mn.* from Design_Geology mn
left join Con_Contract con on con.Con_Id=mn.Con_Id left join Sec_Info sec on sec.Sec_Id=con.Con_Section_Id left join SYS_Company c1 on con.Con_Party_B_Id=c1.C_Id left join SYS_Company c2 on mn.Dg_Exploration_Unit = c2.C_Id
${params.authSql}
where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Dg_Create_Time desc
